import{_ as e,o as n,c as s,al as t}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Analog Video Transmitters","description":"","frontmatter":{},"headers":[],"relativePath":"zh/vtx/index.md","filePath":"zh/vtx/index.md"}'),i={name:"zh/vtx/index.md"};function l(o,a,p,c,r,d){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="analog-video-transmitters" tabindex="-1">Analog Video Transmitters <a class="header-anchor" href="#analog-video-transmitters" aria-label="Permalink to &quot;Analog Video Transmitters&quot;">​</a></h1><p>Analog Video Transmitters (VTX) can be controlled by PX4 via a half-duplex UART connection implementing the SmartAudio v1, v2, and v2.1 and Tramp protocols.</p><p>The protocols allow writing and reading:</p><ul><li>device status.</li><li>transmission frequency in MHz or via band and channel index.</li><li>transmission power in dBm or mW.</li><li>operation modes.</li></ul><p>VTX settings are controlled by parameters and optionally via RC AUX channels or CRSF MSP commands. The driver stores frequency and power tables that map band/channel indices to actual transmission values. Configuration is device-specific and set up using the command line interface.</p><h2 id="入门指南" tabindex="-1">入门指南 <a class="header-anchor" href="#入门指南" aria-label="Permalink to &quot;入门指南&quot;">​</a></h2><p>Connect the SmartAudio or Tramp pin of the VTX to the TX pin of a free serial port on the flight controller. Then set the following parameters:</p><ul><li><code>VTX_SER_CFG</code>: Select the serial port used for VTX communication.</li><li><code>VTX_PROTOCOL</code>: Selects the wire protocol (SmartAudio or Tramp).</li><li><code>VTX_DEVICE</code>: Selects the specific VTX model.</li></ul><p>Note that since the VTX communication is half-duplex, you can, for example, use the single-pin Radio Controller port for the VTX and use a full duplex TELEM port for CRSF communication.</p><p>You should now be able to see the VTX device in the driver status:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nsh&gt; vtx status</span></span>
<span class="line"><span>INFO  [vtx] UART device: /dev/ttyS4</span></span>
<span class="line"><span>INFO  [vtx] VTX table &quot;UNINITIALIZED&quot;:</span></span>
<span class="line"><span>INFO  [vtx] Power levels:</span></span>
<span class="line"><span>INFO  [vtx] RC mapping: Disabled</span></span>
<span class="line"><span>INFO  [vtx] Parameters:</span></span>
<span class="line"><span>INFO  [vtx]   band: 1</span></span>
<span class="line"><span>INFO  [vtx]   channel: 1</span></span>
<span class="line"><span>INFO  [vtx]   frequency: 0 MHz</span></span>
<span class="line"><span>INFO  [vtx]   power level: 1</span></span>
<span class="line"><span>INFO  [vtx]   power: 0 = 0 mW</span></span>
<span class="line"><span>INFO  [vtx]   pit mode: off</span></span>
<span class="line"><span>INFO  [vtx] SmartAudio v2:</span></span>
<span class="line"><span>INFO  [vtx]   band: 1</span></span>
<span class="line"><span>INFO  [vtx]   channel: 1</span></span>
<span class="line"><span>INFO  [vtx]   frequency: 6110 MHz</span></span>
<span class="line"><span>INFO  [vtx]   power level: 1</span></span>
<span class="line"><span>INFO  [vtx]   power: 0 mW</span></span>
<span class="line"><span>INFO  [vtx]   pit mode: on</span></span>
<span class="line"><span>INFO  [vtx]   lock: unlocked</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Without a configured power table, power mappings are unknown and default to 0 mW. Some VTX devices enter pit mode when power is set to 0, regardless of the <code>VTX_PIT_MODE</code> parameter.</p></div><h2 id="vtx-table-configuration" tabindex="-1">VTX Table Configuration <a class="header-anchor" href="#vtx-table-configuration" aria-label="Permalink to &quot;VTX Table Configuration&quot;">​</a></h2><p>The VTX table stores frequency and power mappings for your specific device.</p><p>The manufacturer usually provides this information in the form of a JSON file that can be translated into a <a href="https://betaflight.com/docs/wiki/guides/current/VTX#vtx-tables" target="_blank" rel="noreferrer">Betaflight CLI command set</a> that this driver implements for compatibility.</p><h3 id="power-level-configuration" tabindex="-1">Power Level Configuration <a class="header-anchor" href="#power-level-configuration" aria-label="Permalink to &quot;Power Level Configuration&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Set table name ≤16 characters</span></span>
<span class="line"><span>vtxtable name &quot;Peak THOR T67&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Set the power values that are sent to the VTX for each power level index</span></span>
<span class="line"><span># Note: SmartAudio v1 and v2 use index values!</span></span>
<span class="line"><span>vtxtable powervalues 0 1 2 3 4</span></span>
<span class="line"><span># Note: SmartAudio v2.1 uses dBm values instead!</span></span>
<span class="line"><span>#       vtxtable powervalues 14 23 27 30 35</span></span>
<span class="line"><span># Note: Tramp uses mW values instead!</span></span>
<span class="line"><span>#       vtxtable powervalues 25 200 500 1000 3000</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Set the corresponding power labels for each power level index ≤4 characters.</span></span>
<span class="line"><span># These are used for status reporting.</span></span>
<span class="line"><span>vtxtable powerlabels 25 200 500 1W 3W</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Set number of power levels</span></span>
<span class="line"><span>vtxtable powerlevels 5</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Save configuration</span></span>
<span class="line"><span>vtxtable save</span></span></code></pre></div><p>This will create a VTX table with 5 power levels.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nsh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vtxtable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable] VTX table </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Peak THOR T67&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable] Power levels:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable]   1:  0 = 25</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable]   2:  1 = 200</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable]   3:  2 = 500</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable]   4:  3 = 1W</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">INFO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [vtxtable]   5:  4 = 3W</span></span></code></pre></div><h3 id="frequency-table-configuration" tabindex="-1">Frequency Table Configuration <a class="header-anchor" href="#frequency-table-configuration" aria-label="Permalink to &quot;Frequency Table Configuration&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Set the name of each band and the frequencies of each channel</span></span>
<span class="line"><span>vtxtable band 1 BAND_A A FACTORY 6110 6130 6150 6170 6190 6210 6230 6250</span></span>
<span class="line"><span>vtxtable band 2 BAND_B B FACTORY 6270 6290 6310 6330 6350 6370 6390 6410</span></span>
<span class="line"><span>vtxtable band 3 BAND_E E FACTORY 6430 6450 6470 6490 6510 6530 6550 6570</span></span>
<span class="line"><span>vtxtable band 4 BAND_F F FACTORY 6590 6610 6630 6650 6670 6690 6710 6730</span></span>
<span class="line"><span>vtxtable band 5 BAND_R R FACTORY 6750 6770 6790 6810 6830 6850 6870 6890</span></span>
<span class="line"><span>vtxtable band 6 BAND_P P FACTORY 6910 6930 6950 6970 6990 7010 7030 7050</span></span>
<span class="line"><span>vtxtable band 7 BAND_H H FACTORY 7070 7090 7110 7130 7150 7170 7190 7210</span></span>
<span class="line"><span>vtxtable band 8 BAND_U U FACTORY 6115 6265 6425 6585 6745 6905 7065 7185</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Set number of bands and channels</span></span>
<span class="line"><span>vtxtable bands 8</span></span>
<span class="line"><span>vtxtable channels 8</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Save configuration</span></span>
<span class="line"><span>vtxtable save</span></span></code></pre></div><p>This will create a VTX table with 8 bands and 8 channels. Note that FACTORY sends the band and channel indexes to the VTX device and they use their internal frequency mapping. In this mode the frequency is just for indication purposes. In contrast, CUSTOM would send the actual frequency values to the VTX device, but not all devices support this mode. Setting a frequency to zero will skip setting it.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nsh&gt; vtxtable status</span></span>
<span class="line"><span>INFO  [vtxtable] VTX table 8x8: Peak THOR T67</span></span>
<span class="line"><span>INFO  [vtxtable]  A: BAND_A          = 6110 6130 6150 6170 6190 6210 6230 6250</span></span>
<span class="line"><span>INFO  [vtxtable]  B: BAND_B          = 6270 6290 6310 6330 6350 6370 6390 6410</span></span>
<span class="line"><span>INFO  [vtxtable]  E: BAND_E          = 6430 6450 6470 6490 6510 6530 6550 6570</span></span>
<span class="line"><span>INFO  [vtxtable]  F: BAND_F          = 6590 6610 6630 6650 6670 6690 6710 6730</span></span>
<span class="line"><span>INFO  [vtxtable]  R: BAND_R          = 6750 6770 6790 6810 6830 6850 6870 6890</span></span>
<span class="line"><span>INFO  [vtxtable]  P: BAND_P          = 6910 6930 6950 6970 6990 7010 7030 7050</span></span>
<span class="line"><span>INFO  [vtxtable]  H: BAND_H          = 7070 7090 7110 7130 7150 7170 7190 7210</span></span>
<span class="line"><span>INFO  [vtxtable]  U: BAND_U          = 6115 6265 6425 6585 6745 6905 7065 7185</span></span></code></pre></div><h3 id="table-constraints" tabindex="-1">Table Constraints <a class="header-anchor" href="#table-constraints" aria-label="Permalink to &quot;Table Constraints&quot;">​</a></h3><p>Maximum table dimensions:</p><ul><li>≤24 bands each with ≤16 channels and ≤32GHz frequency values.</li><li>≤16 power levels.</li><li>≤16 characters table name.</li><li>≤12 characters band name and 1 character band letter.</li><li>≤4 characters power label length (to support &quot;2.5W&quot;).</li></ul><h2 id="aux-channel-mapping" tabindex="-1">AUX Channel Mapping <a class="header-anchor" href="#aux-channel-mapping" aria-label="Permalink to &quot;AUX Channel Mapping&quot;">​</a></h2><p>The AUX mapping feature allows you to control VTX settings using RC AUX channels. Each mapping entry defines an AUX channel range that triggers a specific VTX configuration.</p><p>To enable AUX mapping, set <code>VTX_MAP_CONFIG</code> to one of the following values:</p><ul><li><code>0</code>: Disabled</li><li><code>1</code>: Disabled (reserved for CRSF MSP integration)</li><li><code>2</code>: Map AUX channels to power level control only</li><li><code>3</code>: Map AUX channels to band and channel control only</li><li><code>4</code>: Map AUX channels to all settings (power, band, and channel)</li></ul><h3 id="configuring-aux-map-entries" tabindex="-1">Configuring AUX Map Entries <a class="header-anchor" href="#configuring-aux-map-entries" aria-label="Permalink to &quot;Configuring AUX Map Entries&quot;">​</a></h3><p>Use the following command format to add mapping entries:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vtxtable &lt;index&gt; &lt;aux_channel&gt; &lt;band&gt; &lt;channel&gt; &lt;power&gt; &lt;start_pwm&gt; &lt;end_pwm&gt;</span></span></code></pre></div><p>Parameters:</p><ul><li><code>index</code>: Map entry index (0-159)</li><li><code>aux_channel</code>: AUX channel number (3-19, where AUX1=3)</li><li><code>band</code>: Target band (1-24, or 0 to leave unchanged)</li><li><code>channel</code>: Target channel (1-16, or 0 to leave unchanged)</li><li><code>power</code>: Power level (1-16, 0 to leave unchanged, or -1 for pit mode)</li><li><code>start_pwm</code>: Start of PWM range in microseconds (typically 900-2100)</li><li><code>end_pwm</code>: End of PWM range in microseconds (typically 900-2100)</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>AUX channel numbering starts from 3 (AUX1=channel 3) to account for the first four RC channels 0-3 used for flight control.</p></div><p>Example configuration for a 6-position dial controlling band/channel on AUX4 (channel 7):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vtx  0 7 7 1 0  900 1025</span></span>
<span class="line"><span>vtx  1 7 7 2 0 1025 1100</span></span>
<span class="line"><span>vtx  2 7 7 4 0 1100 1175</span></span>
<span class="line"><span>vtx  3 7 7 6 0 1175 1225</span></span>
<span class="line"><span>vtx  4 7 7 8 0 1225 1300</span></span>
<span class="line"><span>vtx  5 7 3 8 0 1300 2100</span></span></code></pre></div><p>Example configuration for power control on AUX3 (channel 6):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vtxtable 16 6 0 0 -1  900 1250</span></span>
<span class="line"><span>vtxtable 17 6 0 0  1 1250 1525</span></span>
<span class="line"><span>vtxtable 18 6 0 0  2 1525 1650</span></span>
<span class="line"><span>vtxtable 19 6 0 0  3 1650 1875</span></span>
<span class="line"><span>vtxtable 20 6 0 0  4 1875 2010</span></span></code></pre></div><p>Save the configuration with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vtxtable save</span></span></code></pre></div><p>The map status can be verified with <code>vtxtable status</code>.</p><h2 id="crsf-msp-integration" tabindex="-1">CRSF MSP Integration <a class="header-anchor" href="#crsf-msp-integration" aria-label="Permalink to &quot;CRSF MSP Integration&quot;">​</a></h2><p>When using a CRSF receiver with MSP support, you can control VTX settings directly from your transmitter using MSP commands sent over the CRSF link. This feature must be enabled at compile time with the <code>VTX_CRSF_MSP_SUPPORT</code> Kconfig option.</p><p>To enable CRSF MSP control, set <code>VTX_MAP_CONFIG</code> to one of:</p><ul><li><code>1</code>: MSP controls both frequency (band/channel) and power</li><li><code>2</code>: MSP controls frequency (band/channel) only, AUX controls power</li><li><code>3</code>: MSP controls power only, AUX controls band/channel</li></ul><p>When MSP integration is active, the driver responds to <code>MSP_SET_VTX_CONFIG</code> (0x59) commands. The transmitter can send band, channel, frequency, power level, and pit mode settings via MSP, which are automatically mapped to the corresponding PX4 parameters.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The MSP integration allows seamless VTX control from transmitters that support VTX configuration via Lua scripts or built-in VTX menus without requiring additional hardware switches.</p></div><h2 id="build-configuration" tabindex="-1">Build Configuration <a class="header-anchor" href="#build-configuration" aria-label="Permalink to &quot;Build Configuration&quot;">​</a></h2><p>Both the VTX driver and VTX table support are configured via Kconfig options.</p><p>Key configuration options:</p><ul><li><code>VTX_CRSF_MSP_SUPPORT</code>: Enables CRSF MSP command support (default: disabled)</li><li><code>VTXTABLE_CONFIG_FILE</code>: File path for persistent configuration (default: <code>/fs/microsd/vtx_config</code>)</li><li><code>VTXTABLE_AUX_MAP</code>: Enables AUX channel mapping (default: disabled)</li></ul><h2 id="parameter-reference" tabindex="-1">Parameter Reference <a class="header-anchor" href="#parameter-reference" aria-label="Permalink to &quot;Parameter Reference&quot;">​</a></h2><h3 id="vtx-settings-parameters" tabindex="-1">VTX Settings Parameters <a class="header-anchor" href="#vtx-settings-parameters" aria-label="Permalink to &quot;VTX Settings Parameters&quot;">​</a></h3><ul><li><code>VTX_BAND</code> (0-23): Frequency band selection (Band 1-24 in UI)</li><li><code>VTX_CHANNEL</code> (0-15): Channel within band (Channel 1-16 in UI)</li><li><code>VTX_FREQUENCY</code> (0-32000): Direct frequency in MHz (overrides band/channel when non-zero)</li><li><code>VTX_POWER</code> (0-15): Power level (Level 1-16 in UI, as configured in table)</li><li><code>VTX_PIT_MODE</code> (boolean): Pit mode for reduced power (default: disabled)</li></ul><h3 id="configuration-parameters" tabindex="-1">Configuration Parameters <a class="header-anchor" href="#configuration-parameters" aria-label="Permalink to &quot;Configuration Parameters&quot;">​</a></h3><ul><li><code>VTX_SER_CFG</code>: Serial port assignment for VTX communication</li><li><code>VTX_MAP_CONFIG</code>: Controls how VTX settings are mapped: <ul><li>Without <code>VTX_CRSF_MSP_SUPPORT</code>: <ul><li><code>0</code>: Disabled</li><li><code>1</code>: Disabled</li><li><code>2</code>: AUX controls power only</li><li><code>3</code>: AUX controls band/channel only</li><li><code>4</code>: AUX controls both power and band/channel</li></ul></li><li>With <code>VTX_CRSF_MSP_SUPPORT</code>: <ul><li><code>0</code>: Disabled</li><li><code>1</code>: MSP controls both frequency and power</li><li><code>2</code>: MSP controls frequency, AUX controls power</li><li><code>3</code>: MSP controls power, AUX controls band/channel</li><li><code>4</code>: Not used with MSP support</li></ul></li></ul></li><li><code>VTX_PROTOCOL</code>: Wire protocol used to talk to the VTX (see below)</li><li><code>VTX_DEVICE</code>: Device-specific configuration (see below)</li></ul><h2 id="protocol-and-device-configuration" tabindex="-1">Protocol and Device Configuration <a class="header-anchor" href="#protocol-and-device-configuration" aria-label="Permalink to &quot;Protocol and Device Configuration&quot;">​</a></h2><p>The wire protocol and the device model are configured independently.</p><p><code>VTX_PROTOCOL</code> selects the wire protocol. Set it to the protocol listed in the manual of your VTX:</p><table tabindex="0"><thead><tr><th>值</th><th>Protocol</th></tr></thead><tbody><tr><td><code>0</code></td><td>SmartAudio v1, v2, v2.1</td></tr><tr><td><code>100</code></td><td>Tramp</td></tr></tbody></table><p><code>VTX_DEVICE</code> selects the specific VTX model and only enables device-specific workarounds. Leave at Generic unless your VTX is listed</p><table tabindex="0"><thead><tr><th>值</th><th>设备</th></tr></thead><tbody><tr><td><code>0</code></td><td>Generic</td></tr><tr><td><code>5120</code></td><td>Peak THOR T67</td></tr><tr><td><code>10240</code></td><td>Rush MAX SOLO</td></tr></tbody></table><p>Peak THOR devices speak SmartAudio and the Rush MAX SOLO speaks Tramp, so set <code>VTX_PROTOCOL</code> to match the model you select.</p><h3 id="known-device-workarounds" tabindex="-1">Known Device Workarounds <a class="header-anchor" href="#known-device-workarounds" aria-label="Permalink to &quot;Known Device Workarounds&quot;">​</a></h3><p><strong>Peak THOR T67</strong> (<code>VTX_DEVICE</code> = 5120): This device incorrectly reports pit mode status but otherwise functions normally. The driver applies a workaround to override the reported status with the actual configured state.</p>`,67)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
